let serverCourseData=null,serverRequestKey=crypto.randomUUID();
async function courseworkApi(action,data={}){if(location.port!=='4180')throw Error('Open the local service on port 4180.');const response=await fetch('/api/coursework/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const result=await response.json();if(!response.ok)throw Error(result.error);return result;}
function serverCoursePage(){return heading('Coursework service','AIM310 · Database-backed workspace')+`<section class="card prose"><p>Submissions and grade versions persist in the tenant database. Server identity determines access independently of the demonstration workspace selector. Use synthetic practice work only.</p>${location.port!=='4180'?'<p><a class="button" href="http://127.0.0.1:4180/#server-coursework">Open coursework service</a></p>':''}<p>Sign in using your username, password and authenticator code.</p><button class="button secondary" id="server-refresh">Refresh records</button><div id="server-course-status" role="status"></div></section><div id="server-course-content"></div>`;}
async function loadServerCourse(){const requestedCourse=selectedCourse;const records=await courseworkApi('list');if(requestedCourse!==selectedCourse||!document.getElementById('server-course-content'))return;serverCourseData=records;const d=serverCourseData;document.getElementById('server-course-status').textContent='Authenticated pilot role: '+d.role;document.getElementById('server-course-content').innerHTML=d.assignments.map(a=>`<section class="card prose"><h2>${esc(a.title)}</h2><p>${esc(a.prompt)}</p>${d.role==='student'?`<form id="server-submit" data-assignment="${esc(a.id)}"><label>Text submission<textarea name="body" required maxlength="10000" rows="6"></textarea></label><button class="button">Submit to tenant database</button></form>`:''}</section>`).join('')+`<section class="card prose"><h2>Submission receipts and reviews</h2>${d.submissions.map(s=>`<article class="callout"><h3>Receipt ${esc(s.id)}</h3><p>${esc(s.user)} · ${esc(new Date(s.created*1000).toLocaleString())}</p><pre style="white-space:pre-wrap">${esc(s.body)}</pre>${s.grade?`<p><b>${s.grade.score}/100 · ${s.grade.posted?'Posted':'Unposted'}</b></p><p>${esc(s.grade.feedback)}</p>`:'<p>No released grade.</p>'}${d.role==='instructor'?`<form class="server-grade" data-submission="${esc(s.id)}" data-version="${s.grade?.version||0}"><label>Score /100<input name="score" required type="number" min="0" max="100" step="0.1" value="${s.grade?.score??''}"></label><label>Feedback<textarea name="feedback" required maxlength="5000">${esc(s.grade?.feedback||'')}</textarea></label><button class="button">Save unposted grade</button></form>${s.grade?`<button class="button secondary" data-server-post="${esc(s.id)}" data-version="${s.grade.version}" data-posted="${!s.grade.posted}">${s.grade.posted?'Hide grade':'Post grade'}</button>`:''}<button class="button secondary" data-server-history="${esc(s.id)}">Grade history</button>`:''}</article>`).join('')||'<p>No submissions.</p>'}</section>`;}
const beforeServerCourse=render;render=function(){if(location.hash==='#server-coursework'){document.getElementById('app').innerHTML=integratedShell('server-coursework',serverCoursePage(),model.role);bind();}else beforeServerCourse();document.querySelector('.sidebar nav')?.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#server-coursework">${icon('book')}Coursework service</a>`);};
document.addEventListener('submit',async e=>{const f=e.target;if(!['server-connect','server-submit'].includes(f.id)&&!f.matches('.server-grade'))return;e.preventDefault();const v=new FormData(f),button=f.querySelector('button');button.disabled=true;try{if(f.id==='server-connect'){governedToken=v.get('token');f.reset();}else if(f.id==='server-submit'){await courseworkApi('submit',{assignment:f.dataset.assignment,body:v.get('body'),request_key:serverRequestKey});serverRequestKey=crypto.randomUUID();}else await courseworkApi('grade',{submission:f.dataset.submission,version:Number(f.dataset.version),score:Number(v.get('score')),feedback:v.get('feedback')});await loadServerCourse();}catch(err){document.getElementById('server-course-status').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const t=e.target.closest('#server-refresh,[data-server-post],[data-server-history]');if(!t)return;try{if(t.dataset.serverHistory){const rows=await courseworkApi('history',{submission:t.dataset.serverHistory});modal('Grade version history','<pre style="white-space:pre-wrap">'+esc(JSON.stringify(rows,null,2))+'</pre>');return;}if(t.dataset.serverPost)await courseworkApi('post',{submission:t.dataset.serverPost,version:Number(t.dataset.version),posted:t.dataset.posted==='true'});await loadServerCourse();}catch(err){document.getElementById('server-course-status').textContent=err.message;}});
render();
